package application.domain.services.order;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport;
public class ConsultOrderService implements ConsultOrderUseCase { private final OrderRepositoryPort orders; public ConsultOrderService(OrderRepositoryPort o){orders=o;} public Order consultOrder(User actor,String id){Order o=ServiceSupport.required(orders.findById(id),"Order",id);ServiceSupport.actor(actor);if(o.getCustomer()!=null&&actor.getCustomer()!=null&&!o.getCustomer().getId().equals(actor.getCustomer().getId())&&!isStaff(actor))throw new application.domain.exceptions.UnauthorizedException("Cannot consult order");return o;} private boolean isStaff(User u){return "ADMIN".equalsIgnoreCase(u.getRole().name())||"EMPLOYEE".equalsIgnoreCase(u.getRole().name())||"SELLER".equalsIgnoreCase(u.getRole().name());}}
